import React from "react";

export function Comp3dElement() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>omerlinks 3D</title>


    <style>
        @keyframes reveal {
            from {
                clip-path: inset(0 100% 0 0);
            }
            to {
                clip-path: inset(0 0 0 0);
            }
        }

        @keyframes textReveal {
            from {
                transform: translateY(100%);
                opacity: 0;
            }
            to {
                transform: translateY(0);
                opacity: 1;
            }
        }

        @keyframes float {
            0%, 100% {
                transform: translateY(0);
            }
            50% {
                transform: translateY(-10px);
            }
        }

        @keyframes shine {
            from {
                transform: translateX(-100%) rotate(45deg);
            }
            to {
                transform: translateX(200%) rotate(45deg);
            }
        }

        @keyframes pulse {
            0%, 100% {
                opacity: 0.4;
            }
            50% {
                opacity: 0.8;
            }
        }

        .shine-effect::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(
                90deg,
                transparent,
                rgba(255, 255, 255, 0.2),
                transparent
            );
            transform: translateX(-100%) rotate(45deg);
        }

        .shine-effect:hover::before {
            animation: shine 1.5s;
        }

        .float-animation {
            animation: float 6s ease-in-out infinite;
        }

        .split-reveal {
            animation: reveal 1.2s cubic-bezier(0.77, 0, 0.175, 1);
        }

        .text-reveal {
            animation: textReveal 0.8s cubic-bezier(0.77, 0, 0.175, 1);
        }

        .scroll-container {
            scroll-snap-type: y mandatory;
            -webkit-overflow-scrolling: touch;
        }

        .scroll-section {
            scroll-snap-align: start;
            scroll-snap-stop: always;
        }

        .content-mask {
            -webkit-mask-image: linear-gradient(to bottom, black 80%, transparent 100%);
            mask-image: linear-gradient(to bottom, black 80%, transparent 100%);
        }

        .three-canvas {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
        }

        .content-overlay {
            position: relative;
            z-index: 10;
        }

        .gradient-text {
            background: linear-gradient(90deg, #3b82f6, #8b5cf6, #ec4899);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            animation: pulse 4s ease-in-out infinite;
        }

        .glass-effect {
            background: rgba(255, 255, 255, 0.05);
            backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .hover-glow:hover {
            box-shadow: 0 0 20px rgba(59, 130, 246, 0.5);
        }

        .nav-dot {
            transition: all 0.3s ease;
        }

        .nav-dot.active {
            background-color: #3b82f6;
            transform: scale(1.5);
        }
    </style>
</head>
<body class="bg-neutral-950 text-white overflow-hidden">
    <!-- Main scroll container -->
    <div class="scroll-container h-screen overflow-y-auto overflow-x-hidden">
        <!-- Section 1 -->
        <section class="scroll-section relative h-screen flex flex-col md:flex-row">
            <!-- Left content with 3D canvas -->
            <div class="w-full md:w-1/2 h-1/2 md:h-full relative overflow-hidden group">
                <div id="canvas1" class="three-canvas"></div>
                <div class="absolute inset-0 bg-gradient-to-r from-neutral-950/70 to-neutral-950/50 transition-opacity duration-500 group-hover:opacity-0"></div>
            </div>
            <!-- Right content -->
            <div class="w-full md:w-1/2 h-1/2 md:h-full flex items-center justify-center p-8 bg-neutral-950 content-overlay">
                <div class="max-w-lg float-animation glass-effect p-8 rounded-2xl">
                    <span class="text-neutral-400 tracking-wider text-sm font-mono">01 / omerlinks</span>
                    <h2 class="mt-4 text-5xl md:text-7xl font-bold leading-none gradient-text">Modern Architecture</h2>
                    <p class="mt-6 text-neutral-400 text-lg leading-relaxed">Exploring the intersection of form and function in contemporary design.</p>
                    <button class="mt-8 px-6 py-3 bg-blue-600/20 hover:bg-blue-600/30 rounded-full text-sm font-medium transition-all duration-300 hover:tracking-wider hover-glow border border-blue-600/30">Explore More →</button>
                </div>
            </div>
        </section>

        <!-- Section 2 -->
        <section class="scroll-section relative h-screen flex flex-col md:flex-row">
            <!-- Right content -->
            <div class="w-full md:w-1/2 h-1/2 md:h-full flex items-center justify-center p-8 bg-neutral-900 content-overlay">
                <div class="max-w-lg float-animation glass-effect p-8 rounded-2xl">
                    <span class="text-neutral-400 tracking-wider text-sm font-mono">02 / omerlinks</span>
                    <h2 class="mt-4 text-5xl md:text-7xl font-bold leading-none gradient-text">Urban Spaces</h2>
                    <p class="mt-6 text-neutral-400 text-lg leading-relaxed">Creating environments that inspire and transform daily life.</p>
                    <button class="mt-8 px-6 py-3 bg-purple-600/20 hover:bg-purple-600/30 rounded-full text-sm font-medium transition-all duration-300 hover:tracking-wider hover-glow border border-purple-600/30">Learn More →</button>
                </div>
            </div>
            <!-- Left content with 3D canvas -->
            <div class="w-full md:w-1/2 h-1/2 md:h-full relative overflow-hidden group">
                <div id="canvas2" class="three-canvas"></div>
                <div class="absolute inset-0 bg-gradient-to-l from-neutral-950/70 to-neutral-950/50 transition-opacity duration-500 group-hover:opacity-0"></div>
            </div>
        </section>

        <!-- Section 3 -->
        <section class="scroll-section relative h-screen flex flex-col md:flex-row">
            <!-- Left content with 3D canvas -->
            <div class="w-full md:w-1/2 h-1/2 md:h-full relative overflow-hidden group">
                <div id="canvas3" class="three-canvas"></div>
                <div class="absolute inset-0 bg-gradient-to-r from-neutral-950/70 to-neutral-950/50 transition-opacity duration-500 group-hover:opacity-0"></div>
            </div>
            <!-- Right content -->
            <div class="w-full md:w-1/2 h-1/2 md:h-full flex items-center justify-center p-8 bg-neutral-950 content-overlay">
                <div class="max-w-lg float-animation glass-effect p-8 rounded-2xl">
                    <span class="text-neutral-400 tracking-wider text-sm font-mono">03 / SPACE</span>
                    <h2 class="mt-4 text-5xl md:text-7xl font-bold leading-none gradient-text">Interior Flow</h2>
                    <p class="mt-6 text-neutral-400 text-lg leading-relaxed">Harmonizing space and light to create immersive experiences.</p>
                    <button class="mt-8 px-6 py-3 bg-pink-600/20 hover:bg-pink-600/30 rounded-full text-sm font-medium transition-all duration-300 hover:tracking-wider hover-glow border border-pink-600/30">Discover More →</button>
                </div>
            </div>
        </section>

        <!-- Navigation dots -->
        <div class="fixed right-8 top-1/2 -translate-y-1/2 flex flex-col gap-4 z-50">
            <button class="nav-dot w-3 h-3 rounded-full bg-white/20 hover:bg-white transition-colors" title="Go to section 1"></button>
            <button class="nav-dot w-3 h-3 rounded-full bg-white/20 hover:bg-white transition-colors" title="Go to section 2"></button>
            <button class="nav-dot w-3 h-3 rounded-full bg-white/20 hover:bg-white transition-colors" title="Go to section 3"></button>
        </div>
    </div>


</body>
</html>" }} />
  );
}
